/**
 * The four fields every policy value carries, and why none is optional.
 *
 * A cap printed without `enforcing` shows a limit that refuses nothing while
 * the rule is a draft. A cap printed without `config_valid` shows a limit the
 * engine is currently failing OPEN on, which is otherwise invisible to the
 * merchant. `state` distinguishes the two not-enforcing states, which
 * merchants read very differently -- see RuleState's docstring.
 */
export type RequiredFields = {
    /**
     * False means there is no such rule row.
     */
    configured: boolean;
    enforcing: boolean;
    /**
     * draft, enforcing, off, or blank when absent.
     */
    state: string;
    config_valid: boolean;
    config_errors: {
        [key: string]: unknown;
    };
    fields: Array<string>;
    count: number;
    /**
     * 'configured' or 'default'.
     */
    source: string;
    /**
     * An explicit empty list. NOT the same as an unconfigured rule, which falls back to the defaults.
     */
    requires_nothing: boolean;
};

export type RevenueCard = {
    window: Window;
    currency: string;
    /**
     * Exactly `window.days` points, zero-filled, in order.
     */
    series: Array<RevenuePoint>;
    total: MoneyCount;
    /**
     * One entry per known agent, zero-filled. These sum to `total`.
     */
    agents: Array<AgentBar>;
    average_basket_paise: number;
    /**
     * The same window immediately before this one -- the comparison this system actually has the facts for.
     */
    prior_window: PriorWindow;
    /**
     * Always null. Munim only ever sees purchases agents made, so there is no storefront average to compare a basket against. See comparison_basis.
     */
    storefront_comparison: number | null;
    /**
     * 'unavailable' today. Named rather than omitted so a client cannot render a ratio from a missing field.
     */
    comparison_basis: string;
    comparison_note: string;
    attribution_caveat: string;
};

